--
-- Table structure for table `road_edges`
--

DROP TABLE IF EXISTS `road_edges`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `road_edges` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `from_node` bigint(20) NOT NULL,
  `to_node` bigint(20) NOT NULL,
  `name` varchar(150) DEFAULT NULL,
  `road_type` varchar(20) NOT NULL DEFAULT 'footway' COMMENT 'footway | service | road | steps | crossing',
  `length_m` decimal(8,2) NOT NULL,
  `cost_factor` decimal(4,2) NOT NULL DEFAULT 1.00,
  `is_bidirectional` tinyint(1) NOT NULL DEFAULT 1,
  `pedestrian_only` tinyint(1) NOT NULL DEFAULT 1,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `geom` linestring NOT NULL,
  PRIMARY KEY (`id`),
  SPATIAL KEY `geom` (`geom`),
  KEY `fk_edge_from_node` (`from_node`),
  KEY `fk_edge_to_node` (`to_node`),
  CONSTRAINT `fk_edge_from_node` FOREIGN KEY (`from_node`) REFERENCES `road_nodes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_edge_to_node` FOREIGN KEY (`to_node`) REFERENCES `road_nodes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3629 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `road_edges`
--

LOCK TABLES `road_edges` WRITE;
