  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_route_orig_place` (`origin_place_id`),
  KEY `fk_route_dest_place` (`dest_place_id`),
  CONSTRAINT `fk_route_dest_place` FOREIGN KEY (`dest_place_id`) REFERENCES `places` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_route_orig_place` FOREIGN KEY (`origin_place_id`) REFERENCES `places` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
